def count_heads(C):
    return C.count('H')

def flip_coin(C, index):
    if index < 1 or index > len(C):
        return C

    C_list = list(C)

    if C_list[index - 1] == 'H':
        C_list[index - 1] = 'T'
    else:
        C_list[index - 1] = 'H'

    return "".join(C_list)

def simulate_game(C):
    turns = 0
    current_C = C
    N = len(C)

    while True:
        k = count_heads(current_C)

        if k == 0:
            break

        # Operation: flip the k-th coin
        current_C = flip_coin(current_C, k)
        turns += 1

    return turns

